insert into public.goals (id, name, description, badge, position) values
  ('learn-ai', 'Learn AI', 'Understand AI basics, prompts, and practical workflows that improve everyday work.', 'AI', 0),
  ('build-website', 'Build a website', 'Learn the basics of design and publishing so you can launch a simple online presence.', 'Web', 1),
  ('automate-work', 'Automate my work', 'Use no-code workflows to handle repetitive tasks and save time in your day.', 'Workflow', 2),
  ('learn-coding', 'Learn coding', 'Start with beginner-friendly coding tools and tiny real-world project ideas.', 'Coding', 3),
  ('learn-ml', 'Learn machine learning', 'Understand the foundations of ML, data patterns, and practical experiments.', 'ML', 4),
  ('design-cad', 'Use CAD and design tools', 'Explore beginner-friendly design, 3D, and product design tools for creative work.', 'Design', 5),
  ('build-app', 'Build an app', 'Turn a product idea into a real first step with a simple app-building roadmap.', 'App', 6),
  ('no-code', 'Use no-code tools', 'Build faster with tools that help you automate, organize, and launch without code.', 'No-code', 7),
  ('ai-productivity', 'Improve AI productivity', 'Learn how AI can help with research, writing, planning, and smarter daily tasks.', 'Productivity', 8),
  ('create-content', 'Create content', 'Make posts, images, voice-overs and short videos with AI helpers, then polish them in your own voice.', 'Content', 9),
  ('analyze-data', 'Analyze data', 'Turn measurements into clear graphs, numbers and decisions with analysis software and AI help.', 'Data', 10),
  ('visualize-data', 'Visualize data', 'Choose clear charts and explain what data shows with honest, accessible visualizations.', 'Data', 11),
  ('research-ai', 'Research with AI', 'Use AI to organise research while finding, checking and citing real sources.', 'Research', 12),
  ('ai-education', 'AI for teachers and students', 'Use AI to support lesson planning, tutoring and practice while protecting privacy and academic integrity.', 'Education', 13)
insert into public.tools (id, name, category, skill, description, badge, url, position) values
  ('chatgpt', 'ChatGPT', 'AI', 'Beginner', 'Helpful for prompt writing, brainstorming, research, and learning how AI works in practice.', 'AI', 'https://chatgpt.com', 0),
  ('claude', 'Claude', 'AI', 'Beginner', 'Good for long-form writing, summarization, and understanding complex ideas more clearly.', 'AI', 'https://claude.ai', 1),
  ('perplexity', 'Perplexity', 'AI', 'Beginner', 'Useful for research, fast answers, and learning across many topics quickly.', 'AI', 'https://www.perplexity.ai', 2),
  ('notion-ai', 'Notion AI', 'AI', 'Beginner', 'Great for notes, summaries, planning, and personal productivity work.', 'Productivity', 'https://www.notion.com/product/ai', 3),
  ('vscode', 'VS Code', 'Coding', 'Beginner', 'The most common editor for learning code and building small projects.', 'Code', 'https://code.visualstudio.com', 4),
  ('git', 'GitHub', 'Coding', 'Beginner', 'Essential for storing code, tracking progress, and collaborating on projects.', 'Code', 'https://github.com', 5),
  ('python', 'Python', 'Coding', 'Beginner', 'A practical language for coding, automation, and data-focused beginner learning.', 'Code', 'https://www.python.org', 6),
  ('figma', 'Figma', 'Design', 'Beginner', 'Great for UI design, mockups, concept exploration, and simple product layout work.', 'Design', 'https://www.figma.com', 7),
  ('canva', 'Canva', 'Design', 'Beginner', 'Useful for posters, presentations, simple visuals, and design-learning projects.', 'Design', 'https://www.canva.com', 8),
  ('zapier', 'Zapier', 'Automation', 'Beginner', 'Connect apps and automate repetitive tasks without writing code.', 'Automation', 'https://zapier.com', 9),
  ('make', 'Make', 'Automation', 'Beginner', 'A visual builder for connecting tools and simplifying everyday digital workflows.', 'Automation', 'https://www.make.com', 10),
  ('n8n', 'n8n', 'Automation', 'Intermediate', 'A flexible automation platform for more advanced workflows and custom integrations.', 'Automation', 'https://n8n.io', 11),
  ('colab', 'Google Colab', 'ML', 'Beginner', 'An easy environment for notebooks, data analysis, and beginner ML experiments.', 'ML', 'https://colab.research.google.com', 12),
  ('kaggle', 'Kaggle', 'ML', 'Beginner', 'A beginner-friendly place to learn from datasets, notebooks, and real examples.', 'ML', 'https://www.kaggle.com', 13),
  ('fusion-360', 'Fusion 360', 'Design', 'Intermediate', 'Helpful for CAD, product thinking, and 3D modeling for conceptual projects.', 'CAD', 'https://www.autodesk.com/products/fusion-360/overview', 14),
  ('gemini', 'Gemini', 'AI', 'Beginner', 'Google''s AI assistant, handy for brainstorming, summarizing and working alongside Google apps.', 'AI', 'https://gemini.google.com', 15),
  ('github-copilot', 'GitHub Copilot', 'Coding', 'Intermediate', 'An AI pair programmer that suggests code and explains it inside your editor.', 'Code', 'https://github.com/features/copilot', 16),
  ('replit', 'Replit', 'Coding', 'Beginner', 'Write, run and share code in the browser with nothing to install.', 'Code', 'https://replit.com', 17),
  ('framer', 'Framer', 'Design', 'Beginner', 'Design and publish a polished website visually, without writing code.', 'Design', 'https://www.framer.com', 18),
  ('airtable', 'Airtable', 'Automation', 'Beginner', 'A friendly spreadsheet-database for organizing data and building simple no-code apps.', 'Automation', 'https://airtable.com', 19),
  ('github', 'GitHub', 'Coding', 'Beginner', 'Store your projects, track changes and collaborate or publish work for free.', 'Code', 'https://github.com', 20),
  ('openai-codex', 'OpenAI Codex', 'Coding', 'Intermediate', 'An AI coding agent that can help explore a codebase, implement changes, and work through software tasks.', 'Code', 'https://chatgpt.com/codex/', 21),
  ('notebooklm', 'NotebookLM', 'AI', 'Beginner', 'Study from your own sources with summaries, study guides, and answers grounded in the materials you add.', 'Research', 'https://notebooklm.google.com', 22),
  ('cursor', 'Cursor', 'Coding', 'Intermediate', 'An AI-powered code editor that helps you write, understand, and improve software alongside your code.', 'Code', 'https://cursor.com', 23),
  ('lovable', 'Lovable', 'Coding', 'Beginner', 'Turn a written app idea into a web prototype, then refine it by describing changes to an AI builder.', 'App', 'https://lovable.dev', 24),
  ('adobe-firefly', 'Adobe Firefly', 'Design', 'Beginner', 'Explore AI-assisted image and design creation with Adobe''s generative tools.', 'Image generation', 'https://firefly.adobe.com', 25),
  ('gamma', 'Gamma', 'Design', 'Beginner', 'Turn an outline into a presentation, document, or simple webpage, then edit the result.', 'Presentations', 'https://gamma.app', 26),
  ('capcut', 'CapCut', 'Design', 'Beginner', 'Edit short videos with templates, captions and simple effects in your browser or on your phone.', 'Video', 'https://www.capcut.com', 27),
  ('elevenlabs', 'ElevenLabs', 'AI', 'Beginner', 'Turn text into natural-sounding speech for voice-overs, using voices you are allowed to use.', 'Voice', 'https://elevenlabs.io', 28),
  ('descript', 'Descript', 'Design', 'Beginner', 'Edit audio and video by editing the written transcript, and remove filler words quickly.', 'Audio & video', 'https://www.descript.com', 29),
  ('microsoft-copilot', 'Microsoft Copilot', 'AI', 'Beginner', 'A free AI assistant for questions, writing help and image ideas, handy if you already use Microsoft tools.', 'Assistant', 'https://copilot.microsoft.com', 30),
  ('originpro', 'Origin / OriginPro', 'Data', 'Intermediate', 'Commercial graphing and data-analysis software for importing data, plotting, statistics, curve fitting and integration.', 'Analysis', 'https://www.originlab.com', 31),
  ('julius-ai', 'Julius AI', 'Data', 'Beginner', 'Chat with an AI assistant to analyse an uploaded spreadsheet or CSV file and draw charts without writing code.', 'Data assistant', 'https://julius.ai', 32)
insert into public.starter_packs (id, title, description, level, file_path, position) values
  ('ai-prompt-pack', 'Beginner AI Starter Pack', 'Helpful prompts, examples, and quick AI workflow ideas for getting started fast.', 'Beginner', 'downloads/ai-prompt-pack.md', 0),
  ('automation-kit', 'No-Code Automation Kit', 'Workflow templates and practical steps for saving time and reducing repetitive work.', 'Beginner', 'downloads/automation-kit.md', 1),
  ('website-bundle', 'Website Starter Bundle', 'A practical toolkit for building and publishing a small online project.', 'Beginner', 'downloads/website-bundle.md', 2),
  ('coding-basics-kit', 'Coding Basics Kit', 'A starter set of learning tasks, concepts, and mini-project ideas.', 'Beginner', 'downloads/coding-basics-kit.md', 3),
  ('ml-workbook', 'ML Foundations Workbook', 'A beginner-friendly workbook for ML concepts, data thinking, and small experiments.', 'Beginner', 'downloads/ml-workbook.md', 4),
  ('productivity-boost', 'AI Productivity Boost', 'Use AI to simplify writing, planning, research, and daily task management.', 'Beginner', 'downloads/productivity-boost.md', 5),
  ('design-starter-kit', 'Design Starter Kit', 'Design principles, a prototyping routine and a feedback checklist for beginners.', 'Beginner', 'downloads/design-starter-kit.md', 6),
  ('app-launch-kit', 'First App Launch Kit', 'A scoped plan for taking a small app idea to a published first version.', 'Intermediate', 'downloads/app-launch-kit.md', 7),
  ('ai-coding-prompts', 'AI Coding Prompt Pack', 'Copy-ready prompts and habits for learning and building with coding assistants.', 'Intermediate', 'downloads/ai-coding-prompts.md', 8),
  ('content-creator-kit', 'AI Content Creator Kit', 'Prompts, a simple creator loop and a responsible-creating checklist for posts, images and short videos.', 'Beginner', 'downloads/content-creator-kit.md', 9),
  ('origin-analysis-kit', 'Origin Data Analysis Kit', 'A menu cheat sheet, key formulas and AI prompt templates for analysing measurement data in Origin.', 'Intermediate', 'downloads/origin-analysis-kit.md', 10),
  ('data-visualization-kit', 'Data Visualization Starter Kit', 'A chart-selection workflow, Colab prompt and review checklist for clear, honest data visuals.', 'Beginner', 'downloads/data-visualization-kit.md', 11),
  ('research-prompt-kit', 'AI Research Prompt Kit', 'Prompts and an evidence workflow for finding, checking and synthesizing real research sources.', 'Beginner', 'downloads/research-prompt-kit.md', 12),
  ('ai-for-education-kit', 'AI for Teachers and Students Kit', 'Practical teacher and student prompts with privacy, verification and academic-integrity checklists.', 'Beginner', 'downloads/ai-for-education-kit.md', 13)
insert into public.paths (id, title, level, description, badge, goal_id, steps, position) values
  ('ai-beginner', 'AI for Beginners', 'Beginner', 'Learn what AI is, how prompts work, and how to use AI in practical day-to-day ways.', 'AI', 'learn-ai', array['Learn the core idea of AI', 'Understand prompt writing', 'Use AI in real tasks', 'Build a small workflow']::text[], 0),
  ('no-code-automation', 'No-Code Automation', 'Beginner', 'Explore practical automation ideas that save time and reduce repetitive work.', 'Automation', 'automate-work', array['Understand workflows', 'Connect simple tools', 'Automate a task', 'Review results and improve']::text[], 1),
  ('web-starter', 'Website Starter', 'Beginner', 'Learn the fundamentals of web structure, publishing, and creating a simple online project.', 'Web', 'build-website', array['Learn web basics', 'Design the layout', 'Build a simple page', 'Publish and share']::text[], 2),
  ('coding-foundations', 'Coding Foundations', 'Beginner', 'Set up your environment, learn core concepts, and build tiny projects with confidence.', 'Code', 'learn-coding', array['Install VS Code and Python, and run your first program', 'Learn variables, types and printing output', 'Use conditions and loops to make decisions', 'Write functions and work with lists', 'Track your code with Git and GitHub', 'Ask an AI assistant like Copilot or Codex to explain code', 'Build and share a mini project']::text[], 3),
  ('ml-foundations', 'ML Foundations', 'Beginner', 'Understand the key ideas behind ML, data patterns, and small practical experiments.', 'ML', 'learn-ml', array['Learn the basics of ML', 'Understand data and patterns', 'Try a notebook', 'Practice with examples']::text[], 4),
  ('ai-productivity', 'AI Productivity Path', 'Beginner', 'Use AI to improve writing, planning, research, and everyday productivity tasks.', 'Productivity', 'ai-productivity', array['Identify useful tasks', 'Define a prompt system', 'Apply AI routines', 'Review and optimize']::text[], 5),
  ('design-basics', 'Design & CAD Basics', 'Beginner', 'Learn core design principles and turn an idea into a simple visual or 3D prototype.', 'Design', 'design-cad', array['Learn basic design principles', 'Sketch an idea and choose a tool', 'Build a simple prototype', 'Gather feedback and refine']::text[], 6),
  ('first-app', 'Build Your First App', 'Intermediate', 'Go from an app idea to a small working first version you can share.', 'Code', 'build-app', array['Write the problem and a tiny scope', 'Sketch the main screens', 'Set up your project with Git and GitHub', 'Build the core feature with an AI coding assistant', 'Test with unusual input and fix bugs', 'Deploy it to a free host', 'Get feedback from a friend and plan version 2']::text[], 7),
  ('no-code-builder', 'No-Code Builder', 'Beginner', 'Build a useful small system with a database and automations, without writing code.', 'Automation', 'no-code', array['Pick a simple problem to solve', 'Organize your data in a table', 'Connect an automation to it', 'Share it and improve it']::text[], 8),
  ('ai-assisted-coding', 'Code With an AI Assistant', 'Intermediate', 'Learn to pair with Copilot or Codex: write clear prompts, review output, and stay in control of your code.', 'Code', 'learn-coding', array['Pick an assistant and set it up in VS Code', 'Describe one small task with a clear prompt', 'Read and understand the generated code', 'Run it and write a simple test', 'Ask the assistant to find bugs and explain fixes', 'Refactor for clear names and small functions', 'Commit with Git and note what you learned']::text[], 9),
  ('content-creation', 'AI Content Creation Path', 'Beginner', 'Plan, draft and polish posts, images and short videos with AI helpers while staying original and honest.', 'Content', 'create-content', array['Choose an audience and a message', 'Draft with an AI assistant', 'Add visuals, voice or video', 'Polish, check facts and share']::text[], 10),
  ('origin-data-analysis', 'Data Analysis with Origin', 'Intermediate', 'Import and plot measurement data, check stability, integrate with weights, map scans and repeat the analysis with templates and AI prompts.', 'Data', 'analyze-data', array['Plan your analysis question', 'Import, label and plot data', 'Measure stability and integrate', 'Map scans, then repeat and report']::text[], 11),
  ('auto-data-analysis', 'Automated Data Analysis', 'Beginner', 'Skip the software settings: use short Python scripts in Colab and AI assistants to analyse measurement files, process many runs at once and validate the results.', 'Data', 'analyze-data', array['Choose an automation route', 'Run scripts on practice data', 'Process many files at once', 'Adapt with AI and validate']::text[], 12),
  ('data-visualization', 'Data Visualization Basics', 'Beginner', 'Choose a chart for your question, prepare a clean table, build a chart in Python and explain the result honestly.', 'Data', 'visualize-data', array['Choose a question and chart', 'Prepare a clean table', 'Create charts in Colab', 'Explain results clearly']::text[], 13),
  ('research-with-ai', 'Prompt Engineering for Research', 'Beginner', 'Turn a broad topic into a focused research question, find real sources, compare evidence and verify every citation.', 'Research', 'research-ai', array['Focus your research question', 'Find and check real sources', 'Build an evidence table', 'Synthesize and verify']::text[], 14),
  ('ai-for-education', 'AI for Teachers and Students', 'Beginner', 'Use practical AI workflows for lesson planning, tutoring and practice while keeping privacy, learning and academic integrity central.', 'Education', 'ai-education', array['Set safe use rules', 'Plan lessons or learn with a tutor', 'Create and review practice', 'Reflect and disclose AI help']::text[], 15)
insert into public.recommendations (goal_id, title, summary, steps) values
  ('learn-ai', 'AI for Beginners', 'Start with AI basics, prompt writing, and simple real-world workflows before moving into deeper tool usage.', array['Understand AI basics', 'Learn prompt writing', 'Use AI in daily tasks', 'Build a small practical project']::text[]),
  ('build-website', 'Website Builder Path', 'Learn the essential steps for designing, creating, and publishing a simple website without feeling lost.', array['Learn structure and design', 'Create a simple layout', 'Publish your first page', 'Refine and share']::text[]),
  ('automate-work', 'Automation Starter', 'Use beginner-friendly tools to reduce repetitive tasks and improve the way you work.', array['Identify a repetitive task', 'Choose a workflow tool', 'Connect two or three tools', 'Test and adjust']::text[]),
  ('learn-coding', 'Coding Foundations', 'Learn the basics of coding and use small projects to build confidence before deeper learning.', array['Set up your workspace', 'Learn basic logic', 'Build a simple script', 'Use AI to explain and review your code', 'Practice with mini projects']::text[]),
  ('learn-ml', 'Machine Learning Foundations', 'Understand the big ideas behind ML, data patterns, and beginner-friendly experiments.', array['Learn key ML concepts', 'Work with data', 'Try a notebook', 'Practice and review']::text[]),
  ('design-cad', 'Design and CAD Path', 'Use design thinking and simple CAD tools to build creative ideas and prototypes with confidence.', array['Learn design basics', 'Explore a tool', 'Create simple concepts', 'Refine and share']::text[]),
  ('build-app', 'App Building Path', 'Start with simple app ideas, product thinking, and the tools that help you build a first version.', array['Define the idea and tiny scope', 'Sketch the user flow', 'Build a prototype with an AI coding assistant', 'Test with real people', 'Publish and improve']::text[]),
  ('no-code', 'No-Code Starter', 'Use easy tools to build workflows and small systems without needing to write code.', array['Choose a simple problem', 'Map the flow', 'Build the workflow', 'Review and improve']::text[]),
  ('ai-productivity', 'AI Productivity Path', 'Learn how AI can support writing, planning, research, and daily work in a practical way.', array['Identify daily repetitive tasks', 'Create reusable prompts', 'Apply AI to real work', 'Review and improve results']::text[]),
  ('create-content', 'Content Creation Path', 'Plan an idea, draft it with AI, add visuals or voice, then polish it in your own voice before you share.', array['Pick one audience and message', 'Draft with an AI assistant', 'Add images, voice or video', 'Edit, check facts and publish']::text[]),
  ('analyze-data', 'Data Analysis Path', 'Learn to import, plot, measure and report on measurement data such as pump logs and scanner maps. Use Origin for graphs, or automate the analysis with Python scripts and AI assistants.', array['Write your analysis question', 'Import, label and plot data', 'Measure stability, integrate and fit', 'Map scans, then template and report']::text[]),
  ('visualize-data', 'Data Visualization Path', 'Use clear charts to answer questions about data. Start with clean tables, choose a chart, create it in Python or Colab and explain its limits.', array['Choose a question and chart', 'Prepare and label data', 'Create and review visualizations', 'Explain the evidence and limitations']::text[]),
  ('research-ai', 'Research Prompting Path', 'Use AI to narrow research questions, organize evidence and draft synthesis, while verifying original sources and every citation yourself.', array['Focus a research question', 'Find real sources', 'Compare evidence and limitations', 'Verify and cite the final brief']::text[]),
  ('ai-education', 'AI for Teachers and Students Path', 'Use AI for lesson planning, tutoring and practice without sharing personal student data or handing over human judgement and learning.', array['Set privacy and course rules', 'Plan a lesson or study with a tutor', 'Create and review practice', 'Reflect on and disclose AI use']::text[])
